import fs from 'node:fs';import path from 'node:path';import {createRequire} from 'node:module';const require=createRequire(import.meta.url),{chromium}=require(path.join(process.env.USERPROFILE,'.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright'));const out='docs/verification/first-real-build-20261106',target=JSON.parse(fs.readFileSync(out+'/prepared-target.json','utf8')),journal=out+'/live-dispatch.json';if(fs.existsSync(journal))throw Error('Dispatch already recorded; do not repeat');const approvedAt=new Date().toISOString();const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true});let dispatched=false;try{const page=await browser.newPage({viewport:{width:1440,height:1000}});await page.route('**/*',r=>new URL(r.request().url()).origin==='http://127.0.0.1:3000'?r.continue():r.abort());await page.goto('http://127.0.0.1:3000/team#project/'+target.projectId+'/chat/'+target.sessionId);await page.waitForFunction(id=>state.studioDetail?.id===id&&!state.busy,target.sessionId);const check=await page.evaluate(()=>({id:state.studioDetail.id,mode:state.studioDetail.state.executionMode,worker:state.studioDetail.state.builderOnlyAgent,executions:state.studioDetail.executions?.length||0,approval:!!state.studioDetail.state.runApproval,project:state.data.studio.projects.find(p=>p.id===state.studioProject)}));if(check.id!==target.sessionId||check.mode!=='builder-only'||check.worker!=='codex-personal'||check.executions||check.approval)throw Error('Target changed; no dispatch');if(!check.project.agentChangesAllowed)await page.evaluate(async({id,version})=>{await api('/studio/projects/'+id+'/access',{enabled:true,version,approvedBy:'owner'});await refresh();},{id:target.projectId,version:check.project.accessVersion});
await page.locator('#chat-execution-tools>summary').click();await page.getByRole('button',{name:'Approve one Builder invocation',exact:true}).click();await page.waitForFunction(()=>!!state.studioDetail?.state.runApproval&&!state.busy);const scope=await page.evaluate(()=>state.studioDetail.state.runApproval);if(scope.maxCalls!==1||scope.timeoutMs!==300000||scope.maxOutputBytes!==32768||scope.roles.builder!=='codex-personal')throw Error('Approval limits mismatch');fs.writeFileSync(journal,JSON.stringify({approvedAt,projectId:target.projectId,sessionId:target.sessionId,scope,dispatchAttemptedAt:new Date().toISOString()},null,2),{flag:'wx'});dispatched=true;await page.getByRole('button',{name:'Send',exact:true}).click();const until=Date.now()+370000;let detail;while(Date.now()<until){detail=await page.evaluate(id=>api('/studio/chats/'+id),target.sessionId);const result={status:detail.status,executionCount:detail.executions?.length||0,events:detail.events?.map(e=>({kind:e.kind,agent:e.agent,created_at:e.created_at})),builderCompleted:!!detail.state.builderCompleted,updatedAt:new Date().toISOString()};fs.writeFileSync(out+'/live-progress.json',JSON.stringify(result,null,2));if(!['ready','running','stopping'].includes(detail.status))break;await new Promise(r=>setTimeout(r,4000));}fs.writeFileSync(out+'/live-result.json',JSON.stringify(detail,null,2));await page.reload();await page.waitForFunction(id=>state.studioDetail?.id===id&&!state.busy,target.sessionId);await page.screenshot({path:out+'/after-live-execution.png',fullPage:true});console.log(JSON.stringify({status:detail.status,executionCount:detail.executions?.length||0,builderCompleted:!!detail.state.builderCompleted,failure:detail.state.failure||null,alert:detail.state.alert||null,modelCallsAttempted:1},null,2));}catch(e){fs.writeFileSync(out+'/dispatch-error.json',JSON.stringify({message:e.message,dispatched,at:new Date().toISOString()},null,2));console.log(JSON.stringify({error:e.message,dispatched}));process.exitCode=1;}finally{await browser.close();}
